using System;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using CircuitoStudio;
class DriveMotorTests {
 static int n;
 static void Check(bool b,string message){n++;if(!b)throw new Exception(message);}
 static void Reject(Action action){try{action();}catch(InvalidDataException){n++;return;}throw new Exception("Invalid drive/motor data accepted");}
 static DriveMotorData Data(){return new DriveMotorData{DriveReference="Inversor ensaio Ç",InputRatedA=15,OutputRatedA=22,OutputVoltageV=380,MotorReference="Motor ensaio Ω",MotorRatedA=20,MotorVoltageV=380,MotorShaftKw=7.5,Source="Dados sintéticos para teste — revisão 1"};}
 [STAThread] static void Main(){string dir=Path.Combine(Path.GetTempPath(),"drive-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
  var p=new Project();var b=new Board{Id="Q1",Voltage=380};var c=new Circuit{Id="C1",PowerKw=8,Voltage=380,PowerFactor=.95,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",DriveMotor=Data()};b.Circuits.Add(c);p.Boards.Add(b);p.Validate();var study=Engineering.Analyze(p);Check(Math.Abs(study.For(c).CurrentA-8000/(Math.Sqrt(3)*380*.95))<1e-10,"Input operating current is derived from electrical input load");Check(study.TotalKw==8,"Motor shaft power is not double-counted");Check(study.Checks.Single(x=>x.Rule=="Inversor: corrente nominal de entrada").Status=="OK","Input nominal comparison");Check(study.Checks.Single(x=>x.Rule=="Inversor: corrente nominal de saída").Status=="OK","Motor nominal compared with output rating");Check(study.Checks.Single(x=>x.Rule=="Inversor: cabo do motor e harmônicas").Status=="Pendente","Unsupported output cable/harmonics remain pending");
  c.DriveMotor.InputRatedA=10;Check(Engineering.Analyze(p).Checks.Single(x=>x.Rule=="Inversor: corrente nominal de entrada").Status=="Falha","Input rating insufficiency");c.DriveMotor=Data();c.DriveMotor.OutputRatedA=19;Check(Engineering.Analyze(p).Checks.Single(x=>x.Rule=="Inversor: corrente nominal de saída").Status=="Falha","Output rating insufficiency");c.DriveMotor=Data();
  string file=Path.Combine(dir,"conjunto.circuito");p.Save(file);var loaded=Project.Load(file).Boards[0].Circuits[0].DriveMotor;Check(loaded.DriveReference==c.DriveMotor.DriveReference&&loaded.MotorReference==c.DriveMotor.MotorReference&&loaded.Source==c.DriveMotor.Source,"Unicode references and source round trip");Check(loaded.InputRatedA==15&&loaded.OutputRatedA==22&&loaded.MotorRatedA==20&&loaded.OutputVoltageV==380&&loaded.MotorVoltageV==380&&loaded.MotorShaftKw==7.5,"All nominal values persist distinctly");
  var copy=c.DriveMotor.Copy();copy.MotorRatedA=100;Check(c.DriveMotor.MotorRatedA==20,"Editing copy does not mutate active record");using(var form=new DriveMotorForm(c)){form.CreateControl();var original=c.DriveMotor;var edited=(DriveMotorData)form.Controls.OfType<PropertyGrid>().Single().SelectedObject;edited.MotorRatedA=99;Check(!form.Changed&&Object.ReferenceEquals(c.DriveMotor,original)&&c.DriveMotor.MotorRatedA==20,"Canceled editor changes do not mutate active record");}
  string memory=EngineeringReport.Memory(p,Engineering.Analyze(p));Check(memory.Contains("entrada de placa 15,000 A")&&memory.Contains("saída de placa 22,000 A")&&memory.Contains("placa 20,000 A"),"Memory identifies all three nominal currents");string html=Path.Combine(dir,"drive.html");c.DriveMotor.DriveReference="<script>teste</script>";EngineeringReport.Html(p,html);Check(File.ReadAllText(html).Contains("&lt;script&gt;teste&lt;/script&gt;")&&!File.ReadAllText(html).Contains("<script>"),"Drive metadata escaped in HTML");c.DriveMotor=Data();
  string materials=Path.Combine(dir,"materiais.csv");EngineeringReport.Materials(p,materials);string materialText=File.ReadAllText(materials);Check(materialText.Contains("Inversor ensaio Ç")&&materialText.Contains("Motor ensaio Ω")&&materialText.Contains("Dados sintéticos"),"Material list preserves both equipment references and source");c.DriveMotor.MotorRatedA=Double.NaN;Reject(delegate{p.Validate();});c.DriveMotor=Data();c.DriveMotor.Source="";Reject(delegate{p.Validate();});c.DriveMotor=Data();c.DriveMotor.OutputVoltageV=0;Reject(delegate{p.Validate();});c.DriveMotor=Data();
  var child=new Board{Id="Q2",Voltage=380};p.Boards.Add(child);c.ChildBoardId="Q2";Reject(delegate{p.Validate();});c.ChildBoardId="";
  c.DriveMotor=null;p.Save(file);Check(Project.Load(file).Boards[0].Circuits[0].DriveMotor==null,"Projects without drive remain supported");Console.WriteLine("PASS: "+n+" drive/motor assertions");
 }finally{Directory.Delete(dir,true);}}
}
